+  a_te_v.reserve(G);
+  b_te_v.reserve(G);
+  a_sf_te_v.reserve(G);
+  b_sf_te_v.reserve(G);
+  aa_te_v.reserve(G);
+  ab_te_v.reserve(G);
+  d_te_v.reserve(G);
