+    const std::vector<size_t> a_sf_shape = {static_cast<size_t>(M), static_cast<size_t>(K / 16)};
+    const std::vector<size_t> b_sf_shape = {static_cast<size_t>(N), static_cast<size_t>(K / 16)};
