+      TensorWrapper in_nvte(NVTE_NVFP4_1D_SCALING);
+      in_nvte.set_rowwise_data(b_data[g].data_ptr(), DType::kFloat4E2M1, b_data_shape);
+      in_nvte.set_rowwise_scale_inv(b_sf[g].data_ptr(), DType::kFloat8E4M3, b_sf_shape);
