+    a_te_v.push_back(
+        makeTransformerEngineTensor(a_data[g].data_ptr(), a_data_shape, DType::kFloat4E2M1));
+    b_te_v.push_back(
+        makeTransformerEngineTensor(b_data[g].data_ptr(), b_data_shape, DType::kFloat4E2M1));
