+      __uint128_t& elts_8x = *reinterpret_cast<__uint128_t*>(&rIn[w]);
+      elts_8x = ptx::ld_shared_b128(&sIn[buff_in][it_offset_Y_rowwise][swizzled_thread_idx]);
